590		ScanCacheVersion int    `json:"scan_cache_version"`
591		FTSSchema        string `json:"fts_schema"`
592	}
593	
594	type brainStatsConversation struct {
595		Exchanges           int            `json:"exchanges"`
596		IncompleteExchanges int            `json:"incomplete_exchanges"`
597		ByBranch            map[string]int `json:"by_branch,omitempty"`
598		ByAgent             map[string]int `json:"by_agent,omitempty"`
599		// Completion state of indexed exchanges: complete ranges vs degraded
600		// (range_incomplete / identity_degraded / projection_truncated).
601		RangeIncomplete     int    `json:"range_incomplete"`
602		IdentityDegraded    int    `json:"identity_degraded"`
603		ProjectionTruncated int    `json:"projection_truncated"`
604		OldestCreatedAt     string `json:"oldest_created_at,omitempty"`
605		LatestCreatedAt     string `json:"latest_created_at,omitempty"`
606		VectorState         string `json:"vector_state"`
607		VectorModelID       string `json:"vector_model_id,omitempty"`
608		Vectors             int    `json:"vectors,omitempty"`
609	}
