611	func newStatsCommand(opts Options) *cobra.Command {
612		var jsonOut bool
613		cmd := &cobra.Command{
614			Use:   "stats",
615			Short: "Show brain record counts and breakdowns",
616			Long:  "Report brain counts and ranges by branch, agent, source, completion state, and index version",
617			Args:  cobra.NoArgs,
618			RunE: func(cmd *cobra.Command, args []string) error {
619				return runBrainStats(cmd.Context(), cmd, opts, jsonOut)
620			},
621		}
622		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit machine-readable JSON")
623		return cmd
624	}
625	
626	func runBrainStats(ctx context.Context, cmd *cobra.Command, opts Options, jsonOut bool) error {
627		target := agentSurfaceTarget(opts, nil)
628		repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, target)
629		if err != nil {
630			return err
631		}
632		if !local {
633			return fmt.Errorf("stats requires a local repository path: %s", target)
634		}
635		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
636		if err != nil {
637			return err
638		}
639		report, err := buildBrainStatsReport(storage.BrainDir, opts.Now().UTC())
640		if err != nil {
641			return err
642		}
643		if jsonOut {
644			return cmdutil.WriteJSON(cmd, report)
645		}
646		return cmdutil.WriteText(cmd, func(out io.Writer) { renderBrainStats(out, report) })
647	}
648	
649	func buildBrainStatsReport(brainDir string, now time.Time) (brainStatsReport, error) {
650		report := brainStatsReport{GeneratedAt: now}
651		manifest, err := bmanifest.Load(brainDir)
652		if err != nil {
653			return report, err
654		}
655		report.RepoKey = manifest.RepoKey
656		if manifest.Sources != nil && manifest.Sources.Sessions != nil {
657			sessions := manifest.Sources.Sessions.Sessions
658			stats := brainStatsSessions{Count: len(sessions), ByBranch: map[string]int{}, ByAgent: map[string]int{}}
659			var oldest, latest time.Time
660			for _, session := range sessions {
661				if session.Branch != "" {
662					stats.ByBranch[session.Branch]++
663				}
664				if session.Agent != "" {
665					stats.ByAgent[session.Agent]++
666				}
667				if !session.CreatedAt.IsZero() {
668					if oldest.IsZero() || session.CreatedAt.Before(oldest) {
669						oldest = session.CreatedAt
670					}
671					if session.CreatedAt.After(latest) {
672						latest = session.CreatedAt
673					}
674				}
675			}
676			if !oldest.IsZero() {
677				stats.Oldest = oldest.UTC().Format(time.RFC3339)
678				stats.Latest = latest.UTC().Format(time.RFC3339)
679			}
680			report.Sessions = stats
681		}
682		report.History = brainStatsHistory{ScanCacheVersion: historyScanCacheVersion, FTSSchema: historyFTSSchema}
683		if manifest.Sources == nil || manifest.Sources.History == nil {
684			return report, nil
685		}
686		history := manifest.Sources.History
687		report.History.GeneratedAt = history.GeneratedAt.UTC().Format(time.RFC3339)
688		index, err := historystore.LoadIndex(brainDir, history)
689		if err != nil {
690			return report, fmt.Errorf("load history index: %w", err)
691		}
692		report.History.Records = len(index.Records)
693		report.History.ByKind = map[string]int{}
694		conversation := brainStatsConversation{
695			IncompleteExchanges: history.IncompleteExchanges,
696			ByBranch:            map[string]int{},
697			ByAgent:             map[string]int{},
698		}
699		var oldest, latest time.Time
700		for _, record := range index.Records {
701			report.History.ByKind[record.Kind]++
702			if record.Kind != conversationKind {
703				continue
704			}
705			conversation.Exchanges++
706			if record.Branch != "" {
707				conversation.ByBranch[record.Branch]++
708			}
709			if record.Agent != "" {
710				conversation.ByAgent[record.Agent]++
711			}
712			if record.RangeIncomplete {
713				conversation.RangeIncomplete++
714			}
715			if record.IdentityDegraded {
716				conversation.IdentityDegraded++
717			}
718			if record.ProjectionTruncated {
719				conversation.ProjectionTruncated++
720			}
721			if created, err := time.Parse(time.RFC3339, record.CreatedAt); err == nil {
722				if oldest.IsZero() || created.Before(oldest) {
723					oldest = created
724				}
725				if created.After(latest) {
726					latest = created
727				}
728			}
729		}
730		if !oldest.IsZero() {
731			conversation.OldestCreatedAt = oldest.UTC().Format(time.RFC3339)
732			conversation.LatestCreatedAt = latest.UTC().Format(time.RFC3339)
733		}
734		if vectorStatus := buildConversationStatus(brainDir, manifest); vectorStatus != nil {
735			conversation.VectorState = vectorStatus.VectorState
736			conversation.VectorModelID = vectorStatus.VectorModelID
737			conversation.Vectors = vectorStatus.Vectors
738		}
739		report.Conversation = &conversation
740		if shortTerm, state := loadHistoryShortTermState(brainDir, history); state != shortTermStateAbsent && (len(shortTerm.Files) > 0 || !shortTerm.complete() || state != shortTermStateCurrent) {
741			stats := brainStatsShortTerm{
742				Files:       len(shortTerm.Files),
743				GeneratedAt: shortTerm.GeneratedAt.UTC().Format(time.RFC3339),
744				Truncated:   shortTerm.Truncated,
745				State:       state,
746				FailedFiles: shortTerm.FailedFiles,
747			}
748			for _, entry := range shortTerm.Files {
749				stats.Records += len(entry.Records)
750				for _, record := range entry.Records {
751					if record.Kind == conversationKind {
752						stats.Exchanges++
753					}
754				}
755			}
756			report.ShortTerm = &stats
757		}
758		return report, nil
759	}
760	
761	func renderBrainStats(out io.Writer, report brainStatsReport) {
762		fmt.Fprintf(out, "repo: %s\n", valueOrUnset(report.RepoKey))
763		fmt.Fprintf(out, "sessions: %d", report.Sessions.Count)
764		if report.Sessions.Oldest != "" {
765			fmt.Fprintf(out, " (%s .. %s)", report.Sessions.Oldest, report.Sessions.Latest)
766		}
767		fmt.Fprintln(out)
768		renderStatsCounts(out, "  by branch", report.Sessions.ByBranch)
769		renderStatsCounts(out, "  by agent", report.Sessions.ByAgent)
770		fmt.Fprintf(out, "history: %d records (scan cache v%d, fts schema %s)\n", report.History.Records, report.History.ScanCacheVersion, report.History.FTSSchema)
771		renderStatsCounts(out, "  by kind", report.History.ByKind)
772		if c := report.Conversation; c != nil {
773			fmt.Fprintf(out, "conversation: %d exchanges (%d incomplete, %d range-incomplete, %d degraded-identity, %d truncated-projection)\n",
774				c.Exchanges, c.IncompleteExchanges, c.RangeIncomplete, c.IdentityDegraded, c.ProjectionTruncated)
775			if c.OldestCreatedAt != "" {
776				fmt.Fprintf(out, "  sessions span %s .. %s\n", c.OldestCreatedAt, c.LatestCreatedAt)
777			}
778			renderStatsCounts(out, "  by branch", c.ByBranch)
779			renderStatsCounts(out, "  by agent", c.ByAgent)
780			line := "  vectors: " + c.VectorState
781			if c.VectorState == "current" {
782				line += fmt.Sprintf(" (%d, %s)", c.Vectors, c.VectorModelID)
783			}
784			fmt.Fprintln(out, line)
785		}
786		if s := report.ShortTerm; s != nil {
787			line := fmt.Sprintf("short-term memory: %d records (%d exchanges) from %d changed transcripts (built %s)", s.Records, s.Exchanges, s.Files, s.GeneratedAt)
788			if s.State != "" && s.State != shortTermStateCurrent {
789				line += "; state " + s.State
790			}
791			if s.Truncated {
792				line += "; buffer full, consolidate with `" + base.BrainInvocation(os.LookupEnv, "refresh") + "`"
793			}
794			if len(s.FailedFiles) > 0 {
795				line += fmt.Sprintf("; %d transcripts failed to scan", len(s.FailedFiles))
796			}
797			fmt.Fprintln(out, line)
798		}
799	}
800	
801	func renderStatsCounts(out io.Writer, label string, counts map[string]int) {
802		if len(counts) == 0 {
803			return
804		}
805		keys := make([]string, 0, len(counts))
806		for key := range counts {
807			keys = append(keys, key)
808		}
809		sort.Strings(keys)
810		fmt.Fprint(out, label+":")
811		for _, key := range keys {
812			fmt.Fprintf(out, " %s=%d", key, counts[key])
813		}
814		fmt.Fprintln(out)
815	}
