255	// --- eval (history eval) -----------------------------------------------------
256	
257	// historyEvalArm ranks the index for one query and returns the surfaced
258	// records, or an error when the arm's machinery is unavailable — an eval must
259	// fail loudly rather than silently measure a fallback arm.
260	type historyEvalArm func(query string, k int) ([]historyRecord, error)
261	
262	func newHistoryEvalCommand(opts Options) *cobra.Command {
263		var (
264			tasksFile string
265			branch    string
266			k         int
267			arm       string
268			cutoff    float64
269			jsonOut   bool
270		)
271		cmd := &cobra.Command{
272			Use:   "history-eval --tasks <file>",
273			Short: "Measure history-retrieval quality (tokens, precision, useful-records-per-1k) over held-out tasks",
274			Long: `history-eval runs a labeled task set (from history-eval-gen) through one history
275	retrieval arm and reports the same metrics as 'facts eval' — surfaced records,
276	estimated tokens, precision, recall, useful-per-1k — so 'facts eval-compare'
277	works on the summaries unchanged.
278	
279	Arms:
280	  substring  the pre-BM25 coverage-gate scorer (the 1a baseline)
281	  bm25       the shipped FTS5 ranker; --cutoff sweeps its relevance cutoff
282	  fused      removed with semantic retrieval (trail #278); the flag errors`,
283			Args: cobra.NoArgs,
284			RunE: func(cmd *cobra.Command, args []string) error {
285				if strings.TrimSpace(tasksFile) == "" {
286					return fmt.Errorf("--tasks <file> is required")
287				}
288				tasks, err := loadEvalTasks(tasksFile)
289				if err != nil {
290					return err
291				}
292				_, brainDir, _, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
293				if err != nil {
294					return err
295				}
296				manifest, err := bmanifest.Load(brainDir)
297				if err != nil {
298					return err
299				}
300				if manifest.Sources == nil {
301					return errors.New("brain has no sources; run `" + base.BrainInvocation(os.LookupEnv, "refresh") + "` first")
302				}
303				index, err := historystore.LoadIndex(brainDir, manifest.Sources.History)
304				if err != nil {
305					return err
306				}
307				armFn, err := selectHistoryEvalArm(arm, brainDir, index, cutoff)
308				if err != nil {
309					return err
310				}
311				results, err := runHistoryEval(tasks, k, armFn)
312				if err != nil {
313					return err
314				}
315				summary := summarizeEval(results)
316				summary.Arm = arm
317				if jsonOut {
318					return cmdutil.WriteJSON(cmd, summary)
319				}
320				printEvalSummary(cmd, summary)
321				return nil
322			},
323		}
324		cmd.Flags().StringVar(&tasksFile, "tasks", "", "Path to the held-out task set (JSON array, from history-eval-gen)")
325		cmd.Flags().StringVar(&branch, "branch", "", "Brain branch context (default: current branch)")
326		cmd.Flags().IntVar(&k, "k", 10, "Records to retrieve per task")
327		cmd.Flags().StringVar(&arm, "arm", "bm25", "Retrieval arm: substring | bm25")
328		cmd.Flags().Float64Var(&cutoff, "cutoff", historyFTSRelevanceCutoff, "BM25 relevance cutoff (fraction of the top score) for the bm25/fused arms")
329		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the summary as JSON")
330		return cmd
331	}
332	
333	func selectHistoryEvalArm(arm, brainDir string, index historyIndex, cutoff float64) (historyEvalArm, error) {
334		switch arm {
335		case "substring":
336			return func(query string, k int) ([]historyRecord, error) {
337				return rankHistoryRecords(index, "history", query, k), nil
338			}, nil
339		case "bm25":
340			return func(query string, k int) ([]historyRecord, error) {
341				// A query with no usable FTS terms (e.g. all stopwords: "fix") is a
342				// deterministic honest empty — the same as the fused arm's lexical
343				// side — not a harness failure. Only a real index fault errors.
344				if historyFTSMatchExpr(query) == "" {
345					return nil, nil
346				}
347				scored, ok := rankHistoryViaFTSCutoff(brainDir, index, "history", query, k, cutoff)
348				if !ok {
349					return nil, fmt.Errorf("bm25 arm unavailable for query %q (FTS index failed to build or query failed)", query)
350				}
351				return historyRecordsOf(scored), nil
352			}, nil
353		case "fused":
354			return nil, fmt.Errorf("--arm fused was removed with semantic retrieval (trail #278)")
355		default:
356			return nil, fmt.Errorf("unknown arm %q (substring | bm25)", arm)
357		}
358	}
359	
360	func historyRecordsOf(scored []scoredHistoryRecord) []historyRecord {
361		out := make([]historyRecord, 0, len(scored))
362		for _, s := range scored {
363			out = append(out, s.Record)
364		}
365		return out
366	}
367	
368	func runHistoryEval(tasks []evalTask, defaultK int, arm historyEvalArm) ([]evalTaskResult, error) {
369		results := make([]evalTaskResult, 0, len(tasks))
370		for _, task := range tasks {
371			k := task.K
372			if k <= 0 {
373				k = defaultK
374			}
375			surfaced, err := arm(task.Task, k)
376			if err != nil {
377				return nil, fmt.Errorf("task %s: %w", task.ID, err)
378			}
379			relevant := make(map[string]struct{}, len(task.Relevant))
380			for _, id := range task.Relevant {
381				relevant[id] = struct{}{}
382			}
383			res := historyEvalMetrics(surfaced, relevant, len(relevant))
384			res.ID, res.Task, res.QueryType, res.Labeled = task.ID, task.Task, task.QueryType, len(task.Relevant) > 0
385			if res.Labeled {
386				// Provenance labels, declared as such: eval-compare pairs two
387				// history runs as same-truth, and EvidenceBasis stays proxy (the
388				// labels are silver, never proof-grade).
389				res.RelevanceSource = evalRelevanceExplicitLabel
390				res.LabelSource = normalizedEvalLabelSource(task)
391			}
392			results = append(results, res)
393		}
394		return results, nil
395	}
396	
397	// historyEvalMetrics mirrors evalMetrics over history records. The token
398	// estimate covers what an agent actually loads per surfaced record: the
399	// summary (already truncated to 700 chars at index time) plus its provenance
400	// path.
401	func historyEvalMetrics(surfaced []historyRecord, relevant map[string]struct{}, totalRelevant int) evalTaskResult {
402		chars := 0
403		for _, r := range surfaced {
404			chars += len(r.Summary) + len(r.Path) + 4 // small per-record framing
405		}
406		res := evalTaskResult{Surfaced: len(surfaced), Tokens: (chars + 3) / 4}
407		for _, r := range surfaced {
408			if _, ok := relevant[r.ID]; ok {
409				res.RelevantSurfaced++
410			}
411		}
412		if res.Surfaced > 0 {
413			res.Precision = float64(res.RelevantSurfaced) / float64(res.Surfaced)
414		}
415		if totalRelevant > 0 {
416			res.Recall = float64(res.RelevantSurfaced) / float64(totalRelevant)
417		}
418		if res.Tokens > 0 {
419			res.UsefulPer1k = float64(res.RelevantSurfaced) / (float64(res.Tokens) / 1000.0)
420		}
421		return res
422	}
