21	
22	// lifecycle_ops.go is Phase 3 (lifecycle reliability and operations) of the
23	// conversational-memory plan: observability for the capture -> export -> index
24	// -> recall chain. Automatic indexing itself is inherited (`watch` already
25	// drives the deterministic refresh that builds exchanges), so what lives here
26	// is the explanation layer: doctor's capture-to-recall checks and the stats
27	// surface (counts/ranges by branch, agent, source, completion state, and index
28	// version).
29	
30	// doctorScope says what kind of claim a finding is making, because doctor makes
31	// two of them -- its own Short is "Check the plugin environment AND the
32	// capture-to-recall chain" -- and only one of them is about the thing doctor is
33	// diagnosing.
34	//
35	// A brain-scoped finding is a claim about data this process owns and can name
36	// the repair for: `facts: error` means this store is unreadable, and
37	// re-distilling fixes it.
38	//
39	// An environment-scoped finding is a claim about the surrounding machine --
40	// most of all about the Entire CLI, a different product that entire-brain does
41	// not install, does not execute, and cannot repair. The brain is fully
42	// readable and queryable without it: every entire-brain command works, which is
43	// exactly what CI demonstrates by running the whole suite on a runner that has
44	// no `entire` on PATH. So the absence of the host CLI is not evidence that
45	// anything is wrong with the brain, and it must not decide doctor's exit code
46	// on behalf of one. It is still REPORTED, at full severity -- see
47	// doctorGateFailure for why severity and gating are separated rather than the
48	// finding being softened.
49	const (
50		doctorScopeBrain       = "brain"
51		doctorScopeEnvironment = "environment"
52	)
53	
54	// doctorCheckResult is one finding. Scope is omitted for brain-scoped findings,
55	// which is the default and the overwhelming majority: an absent "scope" in the
56	// JSON contract means "brain", so existing readers are unaffected and only the
57	// exceptions are called out.
58	type doctorCheckResult struct {
59		Name   string `json:"name"`
60		State  string `json:"state"` // ok | warn | error
61		Detail string `json:"detail,omitempty"`
62		Scope  string `json:"scope,omitempty"` // "" (brain) | environment
63	}
64	
65	// scope resolves the omitted default, so the "absent means brain" rule lives in
66	// code rather than only in a comment.
67	func (d doctorCheckResult) scope() string {
68		if d.Scope == "" {
69			return doctorScopeBrain
70		}
71		return d.Scope
72	}
73	
74	// environmental returns true when the finding is a claim about the host
75	// machine rather than about this brain.
76	func (d doctorCheckResult) environmental() bool { return d.scope() == doctorScopeEnvironment }
77	
78	func memoryDoctorChecks(snapshot memoryReadOnlyHealthSnapshot) []doctorCheckResult {
79		checks := make([]doctorCheckResult, 0, 15)
80		add := func(name, state, detail string) {
81			checks = append(checks, doctorCheckResult{Name: name, State: state, Detail: detail})
82		}
83		// addEnvironment records a finding about the host machine: reported in
84		// full, never a reason for doctor to fail a brain.
85		addEnvironment := func(name, state, detail string) {
86			checks = append(checks, doctorCheckResult{Name: name, State: state, Detail: detail, Scope: doctorScopeEnvironment})
87		}
88		install, _ := snapshot.Payload["install"].(map[string]any)
89		if binary, ok := install["entire_binary"].(memoryInstallBinaryHealth); ok {
90			// "present_unproven" is the SUCCESS case: the entire executable was
91			// found on PATH at an absolute path. Reporting it as a warning because
92			// doctor declined to execute it made a correct install indistinguishable
93			// from a broken one on every healthy machine, forever -- doctor never
94			// executes the host binary, so nothing a user could do would clear it.
95			// The three states that are real problems stay errors.
96			//
97			// Environment-scoped: this is the host Entire CLI, not the brain. Note
98			// the shape of the claim -- it can only ever fire when entire-brain was
99			// run directly, because reaching doctor through `entire brain doctor`
100			// means `entire` is on PATH by definition. So it fires exactly for the
101			// people running CI, a container, a fresh checkout, or an evaluation
102			// before installing the suite: for whom a missing host CLI is expected,
103			// not broken.
104			state := "ok"
105			detail := "found at " + binary.Path
106			switch binary.State {
107			case "not_found":
108				state, detail = "error", "the entire executable is not on PATH"
109			case "unsafe_relative_path":
110				state, detail = "error", "the entire executable resolves through a relative PATH entry: "+binary.Path
111			case "lookup_failed":
112				state, detail = "error", "could not look up the entire executable on PATH"
113			}
114			if binary.RecommendedAction != "" && state != "ok" {
115				detail += "; " + binary.RecommendedAction
116			}
117			addEnvironment("memory_install", state, detail)
118		}
119		// There is deliberately no memory_host_adapter check. It reported the
120		// literal state "ok" on every run of every install, because
121		// memoryInstallHealth constructs memoryHostAdapterHealth with
122		// State/Observability hard-coded to "not_observable" (memory_admin.go) and
123		// there is no second construction site -- so no machine, no configuration
124		// and no user action could ever make it say anything else. A line that
125		// cannot vary carries no information, and thirty-four such lines are what
126		// taught readers to skip doctor's output. The underlying payload is NOT
127		// dropped: `doctor --json` still carries it verbatim at
128		// memory.install.host_adapter, with the authority that owns the answer.
129		if coordinator, ok := snapshot.Payload["coordinator"].(map[string]any); ok {
130			stateName, _ := coordinator["state"].(string)
131			state := "ok"
132			detail := stateName
133			if stale, _ := coordinator["stale"].(bool); stale {
134				state = "warn"
135				detail += "; stale heartbeat, next coordinator owner may recover"
136			}
137			if code, _ := coordinator["error_code"].(string); code != "" {
138				state = "error"
139				detail = code
140			}
141			if stateName == "absent" {
142				detail = "no coordinator state yet"
143			}
144			add("memory_coordinator", state, detail)
145		}
146		if locks, ok := snapshot.Payload["locks"].(map[string]any); ok {
147			if writeLock, ok := locks["write"].(map[string]any); ok {
148				lockState, _ := writeLock["state"].(string)
149				state := "ok"
150				detail := lockState + "; read-only inspection does not probe-acquire the lock"
151				switch lockState {
152				case "unsafe", "unavailable":
153					state = "error"
154				case "present_unproven":
155					// NOT a warning. The lock file is created with O_CREATE and is
156					// never unlinked on release, so it exists permanently after the
157					// very first refresh; warning on its presence made every
158					// healthy brain report write_lock: warn forever, and since a
159					// genuinely held lock produces the identical read-only state,
160					// the warning carried no information either way. Liveness is
161					// reported by memory_coordinator (stale heartbeat), which is
162					// the signal that can actually distinguish a stuck refresh.
163					detail += "; the lock leaf persists after release, so presence alone is normal (see memory_coordinator for liveness)"
164				}
165				add("write_lock", state, detail)
166			}
167		}
168		if provider, ok := install["provider_egress"].(map[string]any); ok {
169			state := "ok"
170			detail := fmt.Sprintf("config %v; provider %v; configured egress %v; global policy %v; effective %v", provider["state"], provider["provider"], provider["egress_class"], provider["global_policy"], provider["effective_state"])
171			if code, _ := provider["error_code"].(string); code != "" {
172				state = "error"
173				detail = code
174			} else if effectiveState, _ := provider["effective_state"].(string); strings.HasPrefix(effectiveState, "blocked_") {
175				state = "warn"
176				if blockCode, _ := provider["block_code"].(string); blockCode != "" {
177					detail += "; " + blockCode
178				}
179			} else if providerState, _ := provider["provider_state"].(string); providerState == brainstore.ProviderUnavailCode {
180				state = "warn"
181				detail += "; " + providerState
182			}
183			add("memory_provider_egress", state, detail)
184		}
185		// There is deliberately no memory_schema_capabilities check either. Its
186		// state was the literal "ok" and its detail was formatted purely from
187		// untyped compile-time constants (bmanifest.SchemaVersion = 3,
188		// historyShortTermVersion = 3, historyFTSSchema = "3", memoryVectorSchema
189		// = 2, abstractSchemaVersion = 1, memoryJobSchemaVersion = 2): the same
190		// sentence for every brain built from a given binary. What this build
191		// SUPPORTS is a property of the build, not a diagnosis of the brain --
192		// memory_schemas below is the check that compares it with what is on disk.
193		// `doctor --json` still reports every one of those numbers, at
194		// memory.schemas.compiled_capabilities.
195		schemaState := "error"
196		switch snapshot.ManifestHealth.State {
197		case "current":
198			schemaState = "ok"
199		case "absent":
200			schemaState = "warn"
201		}
202		schemaDetail := fmt.Sprintf("manifest observed state %s, schema %d, compiled support %d", snapshot.ManifestHealth.State, snapshot.ManifestHealth.SchemaVersion, snapshot.ManifestHealth.SupportedSchemaVersion)
203		if snapshot.ManifestHealth.ErrorCode != "" {
204			schemaDetail += "; " + snapshot.ManifestHealth.ErrorCode
205		}
206		if schemas, ok := snapshot.Payload["schemas"].(map[string]any); ok {
207			if observed, ok := schemas["observed_health"].(map[string]any); ok {
208				observedErrors := 0
209				observedWarnings := 0
210				errorCodes := map[string]bool{}
211				for _, value := range observed {
212					if health, ok := value.(map[string]any); ok {
213						state := normalizeMemoryObservedState(memoryObservedStateValue(health["state"]))
214						switch state {
215						case "corrupt", "unsafe", "unsupported", "unavailable":
216							observedErrors++
217						case "stale", "migration_required", "degraded":
218							observedWarnings++
219						}
220						code, _ := health["error_code"].(string)
221						switch code {
222						case brainstore.UnsupportedVersionCode, brainstore.StateCorruptCode, brainstore.StateUnsafeCode, brainstore.MigrationRequiredCode:
223							errorCodes[code] = true
224						}
225					}
226				}
227				if observedErrors > 0 {
228					schemaState = "error"
229					schemaDetail += fmt.Sprintf("; %d observed schema health error(s)", observedErrors)
230				} else if observedWarnings > 0 && schemaState == "ok" {
231					schemaState = "warn"
232					schemaDetail += fmt.Sprintf("; %d stale or migration-required schema observation(s)", observedWarnings)
233				}
234				if len(errorCodes) > 0 {
235					codes := make([]string, 0, len(errorCodes))
236					for code := range errorCodes {
237						codes = append(codes, code)
238					}
239					sort.Strings(codes)
240					schemaDetail += "; " + strings.Join(codes, ", ")
241				}
242			}
243		}
244		add("memory_schemas", schemaState, schemaDetail)
245		for _, artifact := range []struct {
246			name string
247			key  string
248		}{
249			{name: "memory_overlay", key: "overlay"},
250			{name: "memory_fts", key: "fts"},
251			{name: "memory_jobs", key: "job_inventory"},
252			{name: "memory_vectors", key: "vector_progress"},
253		} {
254			if health, ok := snapshot.Payload[artifact.key].(map[string]any); ok {
255				state, _ := health["state"].(string)
256				normalized := normalizeMemoryObservedState(state)
257				checkState := "ok"
258				switch normalized {
259				case "corrupt", "unsafe", "unsupported", "unavailable":
260					checkState = "error"
261				case "stale", "migration_required", "pending", "degraded":
262					checkState = "warn"
263				}
264				detail := normalized
265				if version, ok := health["schema_version"]; ok {
266					detail += fmt.Sprintf("; observed schema %v", version)
267				}
268				if supported, ok := health["supported_schema_version"]; ok {
269					detail += fmt.Sprintf("; supported schema %v", supported)
270				}
271				if code, _ := health["error_code"].(string); code != "" {
272					detail += "; " + code
273				}
274				add(artifact.name, checkState, detail)
275			}
276		}
277		if migrations, ok := snapshot.Payload["migrations"].([]memoryMigrationFinding); ok && len(migrations) > 0 {
278			state := "warn"
279			for _, finding := range migrations {
280				if finding.State == brainstore.StateUnsafeCode || finding.State == brainstore.StateCorruptCode {
281					state = "error"
282					break
283				}
284			}
285			add("memory_migrations", state, fmt.Sprintf("%d derived-state finding(s); inspect with memory migrate dry-run", len(migrations)))
286		} else {
287			add("memory_migrations", "ok", "no derived-state migration findings")
288		}
289		if logHealth, ok := snapshot.Payload["worker_log"].(map[string]any); ok {
290			state := "ok"
291			if code, _ := logHealth["error_code"].(string); code != "" {
292				state = "error"
293			}
294			add("memory_worker_log", state, fmt.Sprintf("%v (bounded to %v bytes)", logHealth["path"], logHealth["max_bytes"]))
295		}
296		if sessions, ok := snapshot.Payload["canonical_sessions"].(map[string]any); ok {
297			stateName, _ := sessions["state"].(string)
298			state := "ok"
299			if stateName != "available" {
300				state = "warn"
301			}
302			if code, _ := sessions["error_code"].(string); code != "" {
303				state = "error"
304				stateName += "; " + code
305			}
306			add("memory_sessions", state, fmt.Sprintf("%s; %v canonical session(s)", stateName, sessions["count"]))
307		}
308		if reconciliation, ok := snapshot.Payload["reconciliation"].(map[string]any); ok {
309			// memoryObservedStateValue, not a .(string) assertion. The projection
310			// receipt's state is a projectionStateReadState, a named string type,
311			// so the assertion failed for EVERY non-current state and printed
312			// "memory_reconciliation: warn" with no reason at all -- exactly when
313			// the reason mattered. The JSON payload had "absent"/"stale" the whole
314			// time; only the human line lost it.
315			stateName := memoryObservedStateValue(reconciliation["state"])
316			state := "warn"
317			if current, _ := reconciliation["current"].(bool); current {
318				state = "ok"
319			}
320			if code := memoryObservedStateValue(reconciliation["error_code"]); code != "" {
321				state = "error"
322				stateName += "; " + code
323			}
324			detail := stateName
325			if at, ok := reconciliation["last_successful_at"]; ok {
326				detail += fmt.Sprintf("; last successful %v", at)
327			}
328			// A state is not advice. projectionStateAction already knows what
329			// clears each one, so carry it instead of leaving the reader to guess.
330			if action := projectionStateAction(projectionStateReadState(memoryObservedStateValue(reconciliation["state"]))); action != "" && state != "ok" {
331				detail += "; " + action
332			}
333			add("memory_reconciliation", state, strings.TrimPrefix(detail, "; "))
334		}
335		return checks
336	}
337	
338	// brainDoctorChecks walks the capture-to-recall chain for one brain:
339	// capture (exported sessions), history index health + freshness against the
340	// current session set, the conversation projection and its vector identity,
341	// the derived FTS index, and the write lock. Every failure is a state, not an
342	// error; doctor's job is to explain, never to crash on a broken brain.
343	func brainDoctorChecks(ctx context.Context, opts Options, target string) []doctorCheckResult {
344		checks, _ := brainDoctorReadOnlyReport(ctx, opts, target)
345		return checks
346	}
347	
348	// brainDoctorReadOnlyReport resolves the Brain and samples its operational
349	// state exactly once. Doctor reuses the returned payload and checks so a
350	// changing heartbeat or filesystem cannot produce a self-contradictory report.
351	func brainDoctorReadOnlyReport(ctx context.Context, opts Options, target string) ([]doctorCheckResult, map[string]any) {
352		var checks []doctorCheckResult
353		var payload map[string]any
354		add := func(name, state, detail string) {
355			checks = append(checks, doctorCheckResult{Name: name, State: state, Detail: detail})
356		}
357		// Durability of the install itself, before anything about this repo: a
358		// plugin living in a temp directory is about to break every command here,
359		// and that is true whether or not the target is a repository.
360		checkEphemeralInstall(add)
361		repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, target)
362		if err != nil || !local {
363			add("brain", "warn", "not a local repository; brain checks skipped")
364			return checks, payload
365		}
366		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
367		if err != nil {
368			add("brain", "error", "brain storage unavailable: "+err.Error())
369			return checks, payload
370		}
371		brainDir := storage.BrainDir
372		snapshot := memoryReadOnlyHealth(brainDir, opts.Now().UTC())
373		payload = snapshot.Payload
374		checks = append(checks, memoryDoctorChecks(snapshot)...)
375		manifest := snapshot.Manifest
376		switch snapshot.ManifestHealth.State {
377		case "current":
378			add("manifest", "ok", brainDir)
379		case "absent":
380			add("manifest", "warn", "absent; run `"+base.BrainInvocation(os.LookupEnv, "refresh")+"`")
381			return checks, payload
382		default:
383			add("manifest", "error", fmt.Sprintf("%s: %s", snapshot.ManifestHealth.ErrorCode, snapshot.ManifestHealth.RecommendedAction))
384			return checks, payload
385		}
386	
387		// Capture: exported sessions are the canonical input to every projection.
388		//
389		// "The sessions stage never ran" and "the sessions stage ran and Entire has
390		// captured nothing yet" were one branch, and it recommended `refresh` for
391		// both. For the second that is a remedy with nothing to do: the export
392		// succeeds, exports zero sessions again, and doctor re-prints the identical
393		// line. A manifest that DECLARES a sessions source is the evidence the
394		// stage ran, so the empty case names what actually produces a session.
395		switch {
396		case manifest.Sources == nil || manifest.Sources.Sessions == nil:
397			add("capture", "warn", "sessions stage has not run; run `"+base.BrainInvocation(os.LookupEnv, "refresh")+"` (sessions stage)")
398		case len(manifest.Sources.Sessions.Sessions) == 0:
399			add("capture", "ok", "no captured sessions yet; Entire has recorded none in this repository -- work in an agent session, then refresh; `entire checkpoint list` shows what Entire itself can see")
400		default:
401			sessions := manifest.Sources.Sessions.Sessions
402			latest := time.Time{}
403			for _, session := range sessions {
404				if session.CreatedAt.After(latest) {
405					latest = session.CreatedAt
406				}
407			}
408			detail := fmt.Sprintf("%d exported sessions", len(sessions))
409			if !latest.IsZero() {
410				detail += ", latest " + latest.UTC().Format(time.RFC3339)
411			}
412			add("capture", "ok", detail)
413		}
414	
415		// Docs projection: the manifest declaring a docs index is not evidence the
416		// index is on disk, and retrieval skips a missing index silently. Name an
417		// unreadable docs layer here rather than letting doctor pass while the
418		// whole layer contributes nothing.
419		if manifest.Sources != nil && manifest.Sources.Docs != nil {
420			if err := docstore.VerifyDeclaredIndex(brainDir); err != nil {
421				add("docs_index", "error", "declared but unreadable: "+err.Error())
422			} else {
423				add("docs_index", "ok", fmt.Sprintf("%d records from %d files", manifest.Sources.Docs.Records, manifest.Sources.Docs.Files))
424			}
425		}
426	
427		// Durable facts: the manifest's fact counts are a claim about the store,
428		// not an observation of it. factstore.Load reads an absent store as an empty
429		// branch, and a readable-but-short facts.ndjson reads as a complete one, so
430		// "facts: ok (5 fact(s))" survived a store that could only produce four.
431		// Cross-check the claim and report the failure at error level; the exit
432		// gate belongs to `doctor --fail-on`, not to this check.
433		if manifest.Sources != nil && manifest.Sources.Facts != nil {
434			facts := manifest.Sources.Facts
435			if integrity := factstore.Inspect(brainDir, facts); !integrity.OK() {
436				add("facts", "error", integrity.Warning())
437			} else {
438				add("facts", "ok", fmt.Sprintf("%d memory(ies) across %d branch(es)", facts.Facts, len(facts.Branches)))
439				branch, branchErr := base.GitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current")
440				if branchErr != nil {
441					add("facts_verification", "warn", "branch unavailable: "+branchErr.Error())
442				} else {
443					if branch == "" {
444						branch = distillDefaultBranch
445					}
446					if summary, err := verificationSummaryForBranch(ctx, opts, repoDir, brainDir, branch); err != nil {
447						add("facts_verification", "warn", err.Error())
448					} else {
449						state := "ok"
450						if summary.Stale > 0 || summary.Orphaned > 0 {
451							state = "warn"
452						}
453						add("facts_verification", state, fmt.Sprintf("branch %s: %d facts, %d verified, %d stale, %d orphaned, %d unverifiable-here", branch, summary.Facts, summary.Verified, summary.Stale, summary.Orphaned, summary.UnverifiableHere))
454					}
455				}
456			}
457		}
458	
459		// History index health and conversation freshness: the projection is fresh
460		// only when it was built from the CURRENT session set (fingerprint match);
461		// a semantic-only refresh must never claim conversation freshness.
462		if manifest.Sources == nil || manifest.Sources.History == nil {
463			add("history_index", "warn", "no history index; run `"+base.BrainInvocation(os.LookupEnv, "refresh")+"`")
464			return checks, payload
465		}
466		history := manifest.Sources.History
467		index, err := historystore.LoadIndex(brainDir, history)
468		if err != nil {
469			add("history_index", "error", "declared but unreadable: "+err.Error())
470			return checks, payload
471		}
472		add("history_index", "ok", fmt.Sprintf("%d records (generated %s)", len(index.Records), history.GeneratedAt.UTC().Format(time.RFC3339)))
473		if history.IndexDigest == "" {
474			add("history_integrity", "warn", "index predates manifest content digests; run `"+base.BrainInvocation(os.LookupEnv, "refresh")+"`")
475		} else {
476			add("history_integrity", "ok", "index bytes match the manifest content digest")
477		}
478		current := brainSessionsFingerprint(brainDir)
479		shortTerm, shortTermState := loadHistoryShortTermState(brainDir, history)
480		// "Covers the gap" is claimable only for a CURRENT overlay built against
481		// the exact current source fingerprint with nothing failed, dropped, or
482		// truncated. Anything less is at best partial coverage.
483		shortTermCurrentForSources := shortTermState == shortTermStateCurrent && shortTerm.SessionsFingerprint == current
484		shortTermCovers := shortTermCurrentForSources && len(shortTerm.Files) > 0
485		switch {
486		case history.SessionsFingerprint == "":
487			add("history_freshness", "warn", "index predates fingerprinting; run `"+base.BrainInvocation(os.LookupEnv, "refresh")+"`")
488		case current == history.SessionsFingerprint:
489			add("history_freshness", "ok", "history and conversation projections were built from the current exported sessions")
490		case shortTermCovers && shortTerm.complete():
491			add("history_freshness", "ok", fmt.Sprintf("long-term index is behind, but short-term memory covers the gap (%d changed transcripts; consolidation pending via `"+base.BrainInvocation(os.LookupEnv, "refresh")+"`)", len(shortTerm.Files)))
492		case shortTermCurrentForSources && !shortTerm.complete():
493			add("history_freshness", "warn", fmt.Sprintf("short-term memory covers the gap only partially (%s); run `"+base.BrainInvocation(os.LookupEnv, "refresh")+"` to consolidate", shortTermIncompleteness(shortTerm)))
494		case shortTermState == shortTermStateCorrupt:
495			add("history_freshness", "warn", "exported sessions changed and the short-term overlay is corrupt; run `"+base.BrainInvocation(os.LookupEnv, "refresh delta")+"` to rebuild it or `"+base.BrainInvocation(os.LookupEnv, "refresh")+"` to consolidate")
496		case shortTermState == shortTermStateUnsupported:
497			add("history_freshness", "warn", "exported sessions changed and the short-term overlay uses an unsupported version; run `"+base.BrainInvocation(os.LookupEnv, "refresh delta")+"` to rebuild it or `"+base.BrainInvocation(os.LookupEnv, "refresh")+"` to consolidate")
498		default:
499			add("history_freshness", "warn", "exported sessions changed since the last index build; run `"+base.BrainInvocation(os.LookupEnv, "refresh delta")+"` for immediate freshness or `"+base.BrainInvocation(os.LookupEnv, "refresh")+"` to consolidate (a missed session-end hook is repaired the same way)")
500		}
501		switch shortTermState {
502		case shortTermStateCorrupt:
503			add("short_term_memory", "warn", "overlay unreadable or invalid (corrupt); rebuild with `"+base.BrainInvocation(os.LookupEnv, "refresh delta")+"`")
504		case shortTermStateUnsupported:
505			add("short_term_memory", "warn", "overlay version unsupported by this binary; rebuild with `"+base.BrainInvocation(os.LookupEnv, "refresh delta")+"`")
506		case shortTermStateCurrent:
507			if len(shortTerm.Files) == 0 && shortTerm.complete() {
508				break
509			}
510			records := 0
511			for _, entry := range shortTerm.Files {
512				records += len(entry.Records)
513			}
514			detail := fmt.Sprintf("%d records from %d changed transcripts (built %s)", records, len(shortTerm.Files), shortTerm.GeneratedAt.UTC().Format(time.RFC3339))
515			state := "ok"
516			if !shortTerm.complete() {
517				state = "warn"
518				detail += "; " + shortTermIncompleteness(shortTerm)
519			}
520			add("short_term_memory", state, detail)
521		}
522	
523		// Conversation projection + vector identity.
524		conversation := buildConversationStatus(brainDir, manifest)
525		if conversation == nil {
526			add("conversation", "warn", "no conversation projection")
527		} else {
528			state := "ok"
529			detail := fmt.Sprintf("%d exchanges (%d incomplete), vectors %s", conversation.Exchanges, conversation.IncompleteExchanges, conversation.VectorState)
530			if conversation.VectorState == "current" {
531				detail += fmt.Sprintf(" (%d, %s)", conversation.Vectors, conversation.VectorModelID)
532			}
533			if conversation.Exchanges == 0 && manifest.Sources.Sessions != nil && len(manifest.Sources.Sessions.Sessions) > 0 {
534				state = "warn"
535				detail += "; sessions exist but produced no exchanges"
536			}
537			add("conversation", state, detail)
538		}
539	
540		// Derived FTS index: an optimization, so absent/stale is a warn (it
541		// rebuilds lazily on the next query), never an error.
542		if db, ferr := openHistoryFTSIfFresh(brainDir, index); ferr == nil && db != nil {
543			_ = db.Close()
544			add("history_fts", "ok", "BM25 index fresh")
545		} else {
546			add("history_fts", "warn", "BM25 index absent or stale; it rebuilds on the next query")
547		}
548	
549		return checks, payload
550	}
