554	type brainStatsReport struct {
555		GeneratedAt  time.Time               `json:"generated_at"`
556		RepoKey      string                  `json:"repo_key,omitempty"`
557		Sessions     brainStatsSessions      `json:"sessions"`
558		History      brainStatsHistory       `json:"history"`
559		Conversation *brainStatsConversation `json:"conversation,omitempty"`
560		// ShortTerm reports the short-term memory overlay (changed transcripts
561		// indexed since the last consolidation), when present.
562		ShortTerm *brainStatsShortTerm `json:"short_term,omitempty"`
563	}
564	
565	type brainStatsShortTerm struct {
566		Files       int    `json:"files"`
567		Records     int    `json:"records"`
568		Exchanges   int    `json:"exchanges"`
569		GeneratedAt string `json:"generated_at"`
570		Truncated   bool   `json:"truncated,omitempty"`
571		// State is the typed overlay load state; FailedFiles are the
572		// transcripts the last delta could not scan.
573		State       string   `json:"state,omitempty"`
574		FailedFiles []string `json:"failed_files,omitempty"`
