19	// history_eval.go is the history-layer retrieval eval — the measurement the
20	// Stage 1a findings left open ("tunable once a history eval lands"). It mirrors
21	// the facts eval (facts_eval.go / facts_eval_gen.go) and reuses its task,
22	// result, and summary machinery, so `facts eval-compare` works on history
23	// summaries unchanged. It exists to answer three questions the alignment plan
24	// gates on this eval:
25	//
26	//  1. The BM25 relevance cutoff and top-k (historyFTSRelevanceCutoff = 0.30 was
27	//     chosen by inspection) — sweep with --cutoff / --k.
28	//  2. Whether a semantic arm fused with the shipped BM25 lifts retrieval —
29	//     Model2Vec measured as noise on history prose, EmbeddingGemma separated
30	//     cleanly on the probe, but the quantitative lift was never measured. Run
31	//     --arm fused (optionally with ENTIRE_BRAIN_EMBEDDER=ollama) vs --arm bm25.
32	//  3. Whether history vectors are worth persisting in the vec0 store at all.
33	//
34	// Tasks are provenance-labeled, exactly like facts eval-gen: each captured
35	// session becomes a task (its opening user request), and the history records
36	// extracted FROM that session's transcript are the ground-truth relevant set.
37	// `request`-kind records are excluded from labels: the general ranking arm
38	// filters them out (they are the query restated), so counting them would cap
39	// recall on records the arm can never surface.
40	
41	// --- task generation (history eval-gen) -------------------------------------
42	
43	func newHistoryEvalGenCommand(opts Options) *cobra.Command {
44		var (
45			out        string
46			limit      int
47			branch     string
48			minRecords int
49			maxRecords int
50			midtask    bool
51		)
52		cmd := &cobra.Command{
53			Use:   "history-eval-gen",
54			Short: "Generate a labeled history-retrieval task set from the brain's own sessions",
55			Long: `history-eval-gen builds a provenance-labeled benchmark for the history layer:
56	each captured session becomes a task (its opening user request), and the history
57	records indexed from that session's transcript are the ground-truth relevant set.
58	Emits a tasks.json consumable by 'history-eval --tasks'.`,
59			Args: cobra.NoArgs,
60			RunE: func(cmd *cobra.Command, args []string) error {
61				_, brainDir, _, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
62				if err != nil {
63					return err
64				}
65				manifest, err := bmanifest.Load(brainDir)
66				if err != nil {
67					return err
68				}
69				if manifest.Sources == nil || manifest.Sources.Sessions == nil {
70					return errors.New("no exported sessions; run `" + base.BrainInvocation(os.LookupEnv, "refresh") + "` first")
71				}
72				index, err := historystore.LoadIndex(brainDir, manifest.Sources.History)
73				if err != nil {
74					return err
75				}
76				tasks := generateHistoryEvalTasksContext(cmd.Context(), brainDir, manifest, index, branch, minRecords, maxRecords, limit, midtask)
77				if len(tasks) == 0 {
78					return fmt.Errorf("no sessions qualified as tasks (need >= %d indexed records and a recoverable opening request)", minRecords)
79				}
80				data, err := json.MarshalIndent(tasks, "", "  ")
81				if err != nil {
82					return err
83				}
84				data = append(data, '\n')
85				if strings.TrimSpace(out) == "" {
86					_, err = cmd.OutOrStdout().Write(data)
87					return err
88				}
89				if err := os.WriteFile(out, data, 0o600); err != nil {
90					return err
91				}
92				fmt.Fprintf(cmd.ErrOrStderr(), "wrote %d tasks to %s\n", len(tasks), out)
93				return nil
94			},
95		}
96		cmd.Flags().StringVar(&out, "out", "", "Write tasks JSON to this file (default: stdout)")
97		cmd.Flags().IntVar(&limit, "limit", 0, "Cap the number of tasks, sampled evenly across strata (0 = all)")
98		cmd.Flags().StringVar(&branch, "branch", "", "Limit to sessions on one branch (default: all)")
99		// History records are far denser per session than facts (~83 median on the
100		// live brain vs the facts eval's 2-30 band): a session emits one record per
101		// decision/validation/tool-path line, not one per durable insight. The
102		// max-records cap therefore sits an order of magnitude above facts
103		// eval-gen's max-facts.
104		cmd.Flags().IntVar(&minRecords, "min-records", 2, "Minimum indexed records for a session to become a task")
105		cmd.Flags().IntVar(&maxRecords, "max-records", 200, "Skip broad sessions with more records than this (diffuse targets); 0 = no cap")
106		cmd.Flags().BoolVar(&midtask, "midtask", true, "Also mine mid-session follow-up questions as a 'midtask' stratum (labels: the records after each question)")
107		return cmd
108	}
109	
110	// queryTypeMidtask is the stratum for mid-session follow-up questions —
111	// an agent's real retrieval moments are narrow in-flight asks ("why does
112	// flush keep branches dirty under --force?"), not session-opening requests.
113	// Tasks in this stratum use the session's LATER request records as queries
114	// and the records that FOLLOW each question as ground truth: the answer to a
115	// mid-task question manifests in the work that came after it.
116	const queryTypeMidtask = "midtask"
117	
118	// midtaskTasksPerSession caps the follow-up questions mined per session so a
119	// long interactive session cannot dominate the benchmark.
120	const midtaskTasksPerSession = 3
121	
122	// generateHistoryEvalTasks maps each qualifying session to one provenance-
123	// labeled opening task plus up to midtaskTasksPerSession mid-task ones. A
124	// record is attributable to a session through its Path — the transcript file
125	// the record was extracted from — which equals the session's manifest
126	// TranscriptPath (both are slash-relative to the brain dir).
127	func generateHistoryEvalTasks(brainDir string, manifest *exportManifest, index historyIndex, branch string, minRecords, maxRecords, limit int, midtask bool) []evalTask {
128		return generateHistoryEvalTasksContext(context.Background(), brainDir, manifest, index, branch, minRecords, maxRecords, limit, midtask)
129	}
130	
131	func generateHistoryEvalTasksContext(ctx context.Context, brainDir string, manifest *exportManifest, index historyIndex, branch string, minRecords, maxRecords, limit int, midtask bool) []evalTask {
132		type pathRecords struct {
133			rankable []historyRecord // non-request records, the labelable set
134			requests []historyRecord // request records, line-ordered below
135		}
136		byPath := map[string]*pathRecords{}
137		seen := map[string]struct{}{}
138		for _, r := range index.Records {
139			if _, dup := seen[r.ID]; dup {
140				continue
141			}
142			seen[r.ID] = struct{}{}
143			pr, ok := byPath[r.Path]
144			if !ok {
145				pr = &pathRecords{}
146				byPath[r.Path] = pr
147			}
148			switch {
149			case r.Kind == "request":
150				pr.requests = append(pr.requests, r)
151			case historyGeneralRankingHiddenKind(r.Kind):
152				// Conversation exchanges are hidden from general ranking, so they
153				// cannot be labelable eval answers either.
154			default:
155				pr.rankable = append(pr.rankable, r)
156			}
157		}
158		for _, pr := range byPath {
159			sort.SliceStable(pr.requests, func(i, j int) bool { return pr.requests[i].Line < pr.requests[j].Line })
160		}
161	
162		var tasks []evalTask
163		withinBounds := func(n int) bool { return n >= minRecords && (maxRecords <= 0 || n <= maxRecords) }
164		for _, s := range manifest.Sources.Sessions.Sessions {
165			if branch != "" && s.Branch != branch {
166				continue
167			}
168			pr := byPath[s.TranscriptPath]
169			if pr == nil || !withinBounds(len(pr.rankable)) {
170				continue
171			}
172			data, readErr := readCanonicalHistoryTranscript(ctx, brainDir, s.TranscriptPath)
173			if readErr != nil {
174				continue
175			}
176			content := string(data)
177			request := firstUserRequest(content)
178			if request == "" {
179				continue
180			}
181			ids := make([]string, 0, len(pr.rankable))
182			for _, r := range pr.rankable {
183				ids = append(ids, r.ID)
184			}
185			sort.Strings(ids)
186			tasks = append(tasks, evalTask{
187				ID:          shortSessionID(s.SessionID),
188				Task:        request,
189				Branch:      s.Branch,
190				QueryType:   classifyHistoryQueryType(request),
191				Relevant:    ids,
192				LabelSource: evalLabelSourceProvenanceSilver, // provenance-derived, never proof-grade
193			})
194			if midtask {
195				tasks = append(tasks, midtaskEvalTasks(s, pr.requests, pr.rankable, minRecords, maxRecords)...)
196			}
197		}
198		tasks = dedupeEvalTasks(tasks)
199		sort.SliceStable(tasks, func(i, j int) bool { return tasks[i].ID < tasks[j].ID })
200		if limit > 0 && len(tasks) > limit {
201			tasks = sampleAcrossStrata(tasks, limit)
202		}
203		return tasks
204	}
205	
206	// midtaskEvalTasks mines a session's follow-up questions: every request
207	// record past the opening one is a candidate query, labeled with the
208	// session's rankable records AFTER that question's line. Wrapper injections
209	// are filtered with the same predicate the opening request uses.
210	func midtaskEvalTasks(s exportSession, requests, rankable []historyRecord, minRecords, maxRecords int) []evalTask {
211		var tasks []evalTask
212		for i, req := range requests {
213			if i == 0 || isWrapperRequest(req.Summary) {
214				continue // the opening request is the session-level task's query
215			}
216			var ids []string
217			for _, r := range rankable {
218				if r.Line > req.Line {
219					ids = append(ids, r.ID)
220				}
221			}
222			if len(ids) < minRecords || (maxRecords > 0 && len(ids) > maxRecords) {
223				continue
224			}
225			sort.Strings(ids)
226			tasks = append(tasks, evalTask{
227				ID:          fmt.Sprintf("%s-m%d", shortSessionID(s.SessionID), req.Line),
228				Task:        req.Summary,
229				Branch:      s.Branch,
230				QueryType:   queryTypeMidtask,
231				Relevant:    ids,
232				LabelSource: evalLabelSourceProvenanceSilver, // provenance-derived, never proof-grade
233			})
234			if len(tasks) >= midtaskTasksPerSession {
235				break
236			}
237		}
238		return tasks
239	}
240	
241	// classifyHistoryQueryType strata: code/howto/concept. The facts classifier's
242	// "convention" stratum keys off fact path scope, which has no history analog
243	// (record paths are transcript files, not code loci).
244	func classifyHistoryQueryType(task string) string {
245		if hasStructuralCodeToken(task) {
246			return queryTypeCode
247		}
248		lower := strings.ToLower(strings.TrimSpace(task))
249		if hasAnyPrefix(lower, "where ", "how do i", "how should", "how can i", "add ", "implement ", "fix ", "wire ", "make ", "build ", "create ", "update ", "remove ") {
250			return queryTypeHowto
251		}
252		return queryTypeConcept
253	}
